package dev.zomboid.isotacz;
import net.minecraft.world.InteractionHand;import net.p3pp3rf1y.sophisticatedbackpacks.backpack.*;
public class BackpackChecks {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public enum Result {PASS,SUCCESS,FAIL;public boolean shouldSwing(){return this==SUCCESS;}public boolean consumesAction(){return this==SUCCESS;}}
 public record Stack(Object item){public Object getItem(){return item;}}
 public static class Player {Stack main=new Stack(new Object()),off=new Stack(new Object());int swings;public Stack getItemInHand(Object hand){return hand==InteractionHand.MAIN_HAND?main:off;}public void swing(Object hand){swings++;}}
 public static class Mode {Result block=Result.PASS;int blockUses,itemUses;Object usedHand;public Object useItemOn(Object player,Object hand,Object hit){blockUses++;return block;}public Object interact(Object player,Object entity,Object hand){return block;}public Object useItem(Object player,Object hand){itemUses++;usedHand=hand;return Result.SUCCESS;}}
 public static class Client {public Player player=new Player();public Mode gameMode=new Mode();public Object hitResult,crosshairPickEntity;}
 public record Entity(double x,double y,double z){public Object blockPosition(){return new net.minecraft.core.BlockPos((int)Math.floor(x),(int)Math.floor(y),(int)Math.floor(z));}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}}
 public record Box(double x,double y,double z){public Box move(double dx,double dy,double dz){return new Box(x+dx,y+dy,z+dz);}}
 public record Hit(){public String getType(){return "BLOCK";}}
 public record State(Object block){public Object getBlock(){return block;}}
 public static class World {public boolean blacklisted;boolean bounds=true;Object block=new BackpackBlock();public boolean isInWorldBounds(Object pos){return bounds;}public State getBlockState(Object pos){return new State(block);}}
 public static void main(String[] args){Client c=new Client();c.player.main=new Stack(new BackpackItem());BackpackInteraction.open(c,new Hit());ok(c.gameMode.itemUses==1&&c.gameMode.usedHand==InteractionHand.MAIN_HAND,"main hand backpack used after block passes");ok(c.player.swings==1,"successful item use swings hand");c=new Client();c.player.off=new Stack(new BackpackItem());BackpackInteraction.open(c,new Hit());ok(c.gameMode.itemUses==1&&c.gameMode.usedHand==InteractionHand.OFF_HAND,"off hand backpack fallback");c=new Client();c.player.main=new Stack(new BackpackItem());c.gameMode.block=Result.SUCCESS;BackpackInteraction.open(c,new Hit());ok(c.gameMode.itemUses==0&&c.gameMode.blockUses==1,"consumed container interaction does not also use item");c=new Client();c.player.main=new Stack(new BackpackItem());c.gameMode.block=Result.FAIL;BackpackInteraction.open(c,new Hit());ok(c.gameMode.itemUses==0&&c.gameMode.blockUses==1,"failed permission interaction stops fallback");c=new Client();BackpackInteraction.open(c,new Hit());ok(c.gameMode.itemUses==0,"does not accidentally use ordinary weapons or items");World w=new World();ok(BackpackInteraction.placed(w,new Object()),"placed backpack classified interactable");w.blacklisted=true;ok(!BackpackInteraction.placed(w,new Object()),"configured blacklist preserved");w.blacklisted=false;w.bounds=false;ok(!BackpackInteraction.placed(w,new Object()),"world bounds preserved");Box box=new Box(1,2,3);ok(PanRecut.shift(box,0,0)==box,"unshifted cutaway preserves original focus");Box shifted=(Box)PanRecut.shift(box,8,-4);ok(shifted.x()==9&&shifted.y()==2&&shifted.z()==-1,"CTRL cutaway focus follows horizontal pan without altering floor height");Bridge.edgeX=4;Bridge.edgeZ=-3;Box focus=(Box)PanRecut.box(box);ok(focus.x()==5&&focus.z()==0,"scan target follows active CTRL offset");Entity entity=new Entity(-.3,65.4,10.8);Object pos=PanRecut.position(entity);ok(pos.equals(new net.minecraft.core.BlockPos(3,65,7)),"room origin follows offset with correct negative coordinate flooring");Bridge.edgeX=0;Bridge.edgeZ=0;ok(PanRecut.box(box)==box,"release returns cutaway to original target");Bridge.edgeX=5;com.cleannrooster.dungeons_iso.mod.Mod.enabled=false;ok(PanRecut.box(box)==box,"disabled isometric mode ignores stale pan offsets");System.out.println("PASS "+n+" backpack interaction checks (API doubles)");}
}
